import React, { useState } from 'react';
import { Outlet, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const ADMIN_BG = '#1A1200';
const ADMIN_AMBER = '#F5A623';
const ADMIN_GREEN = '#2D6A4F';
const ADMIN_LIGHT_BG = '#F4F6F0';

const AdminLayout = () => {
  const { currentUser, logout } = useAuth();
  const navigate = useNavigate();
  const [mobileNavOpen, setMobileNavOpen] = useState(false);

  const handleLogout = () => { logout(); navigate('/'); };

  const links = [
    { to: '/admin/dashboard', icon: 'bi-speedometer2', label: 'Dashboard' },
    { to: '/admin/users', icon: 'bi-people', label: 'Users' },
    { to: '/admin/destinations', icon: 'bi-geo-alt', label: 'Destinations' },
    { to: '/admin/packages', icon: 'bi-briefcase', label: 'Packages' },
    { to: '/admin/hotels', icon: 'bi-building', label: 'Hotels' },
    { to: '/admin/enquiries', icon: 'bi-envelope', label: 'Enquiries' },
    { to: '/admin/reviews', icon: 'bi-star', label: 'Reviews' },
    { to: '/admin/gallery', icon: 'bi-images', label: 'Gallery' },
  ];

  return (
    <div style={{ minHeight: '100vh', background: ADMIN_LIGHT_BG, display: 'flex', flexDirection: 'column' }}>

      {/* ── Top Brand Bar ── */}
      <div style={{ background: ADMIN_BG, padding: '0 28px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', height: 56, position: 'sticky', top: 0, zIndex: 1100 }}>
        {/* Logo */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{ width: 32, height: 32, borderRadius: 8, background: `linear-gradient(135deg, ${ADMIN_GREEN}, ${ADMIN_AMBER})`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <i className="bi bi-compass" style={{ color: 'white', fontSize: '1rem' }}></i>
          </div>
          <span style={{ fontFamily: 'Poppins', fontWeight: 800, color: 'white', fontSize: '1.15rem', letterSpacing: '-0.3px' }}>
            Trip<em style={{ color: ADMIN_AMBER, fontStyle: 'normal' }}>Nova</em>
            <span style={{ fontSize: '0.62rem', background: ADMIN_GREEN, color: 'white', borderRadius: 4, padding: '1px 6px', marginLeft: 8, fontStyle: 'normal', fontWeight: 700, letterSpacing: 1, verticalAlign: 'middle' }}>ADMIN</span>
          </span>
        </div>

        {/* Right: user info + utilities */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 20 }}>
          <NavLink to="/home" style={{ color: 'rgba(255,255,255,0.55)', textDecoration: 'none', fontSize: '0.8rem', display: 'flex', alignItems: 'center', gap: 6 }}>
            <i className="bi bi-box-arrow-up-left"></i>
            <span style={{ display: 'none' }} className="d-sm-inline">Site</span>
          </NavLink>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{ width: 30, height: 30, borderRadius: '50%', background: `linear-gradient(135deg, ${ADMIN_GREEN}, ${ADMIN_AMBER})`, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 700, fontSize: '0.78rem' }}>
              {currentUser?.name?.charAt(0).toUpperCase()}
            </div>
            <span style={{ color: 'rgba(255,255,255,0.75)', fontSize: '0.82rem', fontFamily: 'Inter' }}>{currentUser?.name}</span>
          </div>
          <button onClick={handleLogout} style={{ background: 'rgba(245,166,35,0.15)', border: '1px solid rgba(245,166,35,0.35)', color: ADMIN_AMBER, borderRadius: 6, padding: '4px 14px', cursor: 'pointer', fontSize: '0.78rem', fontWeight: 600 }}>
            <i className="bi bi-box-arrow-right me-1"></i>Logout
          </button>
          {/* mobile hamburger */}
          <button onClick={() => setMobileNavOpen(o => !o)} className="d-md-none" style={{ background: 'none', border: 'none', color: 'white', fontSize: '1.3rem', cursor: 'pointer', padding: 0 }}>
            <i className={`bi ${mobileNavOpen ? 'bi-x-lg' : 'bi-list'}`}></i>
          </button>
        </div>
      </div>

      {/* ── Horizontal Nav Bar ── */}
      <div style={{
        background: ADMIN_GREEN,
        borderBottom: `3px solid ${ADMIN_AMBER}`,
        position: 'sticky', top: 56, zIndex: 1050,
        display: mobileNavOpen ? 'flex' : undefined,
        flexDirection: mobileNavOpen ? 'column' : undefined,
      }} className="d-none d-md-block">
        <nav style={{ display: 'flex', alignItems: 'center', padding: '0 20px', overflowX: 'auto', gap: 2 }}>
          {links.map(link => (
            <NavLink key={link.to} to={link.to} style={({ isActive }) => ({
              display: 'flex', alignItems: 'center', gap: 7,
              padding: '12px 16px',
              color: isActive ? ADMIN_AMBER : 'rgba(255,255,255,0.78)',
              textDecoration: 'none',
              fontFamily: 'Inter', fontSize: '0.82rem', fontWeight: isActive ? 700 : 500,
              borderBottom: isActive ? `3px solid ${ADMIN_AMBER}` : '3px solid transparent',
              marginBottom: -3,
              background: isActive ? 'rgba(0,0,0,0.18)' : 'transparent',
              whiteSpace: 'nowrap',
              transition: 'all 0.18s',
            })}>
              <i className={`bi ${link.icon}`} style={{ fontSize: '0.95rem' }}></i>
              {link.label}
            </NavLink>
          ))}
        </nav>
      </div>

      {/* ── Mobile Nav Dropdown ── */}
      {mobileNavOpen && (
        <div className="d-md-none" style={{ background: ADMIN_GREEN, borderBottom: `2px solid ${ADMIN_AMBER}`, zIndex: 1049, position: 'sticky', top: 56 }}>
          {links.map(link => (
            <NavLink key={link.to} to={link.to} onClick={() => setMobileNavOpen(false)}
              style={({ isActive }) => ({
                display: 'flex', alignItems: 'center', gap: 12, padding: '13px 24px',
                color: isActive ? ADMIN_AMBER : 'rgba(255,255,255,0.78)',
                textDecoration: 'none', fontFamily: 'Inter', fontSize: '0.88rem', fontWeight: isActive ? 700 : 500,
                borderLeft: isActive ? `4px solid ${ADMIN_AMBER}` : '4px solid transparent',
                background: isActive ? 'rgba(0,0,0,0.2)' : 'transparent',
              })}>
              <i className={`bi ${link.icon}`}></i>{link.label}
            </NavLink>
          ))}
        </div>
      )}

      {/* ── Page Content ── */}
      <div style={{ flex: 1, padding: '28px 32px' }}>
        <Outlet />
      </div>
    </div>
  );
};

export default AdminLayout;
